<?php
session_start(); include('check-login.php'); include_once('club-utils.php'); club_ensure_tables($con);
if(!club_is_student()){ header('location:index.php'); exit; }
$uid=$_SESSION['USERID']; $msg='';
if(isset($_POST['join'])){ $club=trim($_POST['clubid']??''); $c=club_detail($con,$club); if(!$c || $c['status']!=='active') $msg='That club is not available.'; elseif(club_member($con,$club,$uid)) $msg='You are already a member.'; else { $id=club_id('MBR');$ce=mysqli_real_escape_string($con,$club);$ue=mysqli_real_escape_string($con,$uid); mysqli_query($con,"INSERT INTO tblclubmember(memberid,clubid,userid,role,status,addedby,joinedat) VALUES('$id','$ce','$ue','member','pending','self',NOW()) ON DUPLICATE KEY UPDATE status='pending',updatedat=NOW()"); club_log($con,$club,$uid,$uid,'requested membership'); $msg='Request sent to the club leader.'; } }
$clubs=mysqli_query($con,"SELECT c.*, (SELECT COUNT(*) FROM tblclubmember m WHERE m.clubid=c.clubid AND m.status='active') members, (SELECT status FROM tblclubmember m WHERE m.clubid=c.clubid AND m.userid='".mysqli_real_escape_string($con,$uid)."' LIMIT 1) my_status FROM tblclub c WHERE c.status='active' ORDER BY c.createdat DESC");
?>
<!doctype html><html><head><?php include('links.php'); ?><link rel="stylesheet" href="css/clubs.css"></head><body class="clubs-page"><div class="header"><?php include('menu.php'); ?></div><main class="clubs-wrap"><section class="clubs-hero"><span>YOUR CAMPUS, YOUR CREW</span><h1>Clubs &amp; Societies</h1><p>Discover your people, build something brilliant, and keep the conversation inside your club.</p></section><?php if($msg){?><div class="clubs-msg"><?php echo club_esc($msg);?></div><?php } ?><section class="club-grid"><?php while($c=mysqli_fetch_assoc($clubs)){ $member=club_member($con,$c['clubid'],$uid); ?><article class="club-card"><div class="club-card__spark">✦</div><h2><?php echo club_esc($c['clubname']);?></h2><p><?php echo club_esc($c['description']);?></p><div class="club-meta"><span><i class="fa fa-users"></i> <?php echo (int)$c['members'];?> members</span><span><i class="fa fa-star"></i> <?php echo club_esc($c['leadername'] ? $c['leadername'] : 'Club leader');?></span></div><?php if($member || $c['leaderid']===$uid){?><a class="club-btn" href="club-room.php?club=<?php echo rawurlencode($c['clubid']);?>">Enter private room <i class="fa fa-arrow-right"></i></a><?php } elseif(($c['my_status']??'')==='pending'){?><span class="club-pending">Request pending</span><?php } else {?><form method="post"><input type="hidden" name="clubid" value="<?php echo club_esc($c['clubid']);?>"><button class="club-btn" name="join">Request to join</button></form><?php } ?></article><?php } ?></section></main></body></html>
